$ErrorActionPreference = 'Stop'
$root = (Get-Location).Path
$project = Join-Path $root 'KMC.Engine\KMC.Engine.csproj'
$tests = Join-Path $root 'Tools\NavigationTests\Program.cs'
$target = Join-Path $root 'KMC.Engine\Navigation\MoonEncounterEvaluator.cs'
$baseline = Join-Path $root 'KMC.Engine\Navigation\MoonTransferBootstrap.cs'
foreach ($path in @($project,$tests,$baseline)) { if (-not (Test-Path $path)) { throw "Missing expected KMC source: $path" } }
if (Test-Path $target) { throw 'MoonEncounterEvaluator.cs already exists. Nothing changed.' }
$projectText = [IO.File]::ReadAllText($project)
$testText = [IO.File]::ReadAllText($tests)
$bootstrapText = [IO.File]::ReadAllText($baseline)
if (-not $bootstrapText.Contains('14.24.1: same-primary')) { throw 'Unexpected moon baseline. Nothing changed.' }
$anchor = '    <Compile Include="Navigation\MoonTransferBootstrap.cs" />'
if (-not $projectText.Contains($anchor)) { throw 'Expected engine project anchor not found. Nothing changed.' }
$testAnchor = '        Run("same-primary moon Lambert injection bootstrap", MoonTransferFoundationRegression);'
if (-not $testText.Contains($testAnchor)) { throw 'Expected test registration missing. Nothing changed.' }
$methodAnchor = '    private static void SchematicAngleSelectionRegression()'
if (-not $testText.Contains($methodAnchor)) { throw 'Expected test method insertion point missing. Nothing changed.' }
$backup = Join-Path $env:TEMP ('KMC_14_24_2_backup_' + (Get-Date -Format 'yyyyMMdd_HHmmss'))
New-Item -ItemType Directory -Path $backup | Out-Null
Copy-Item $project (Join-Path $backup 'KMC.Engine.csproj')
Copy-Item $tests (Join-Path $backup 'Program.cs')
$sourceBase64 = ''
$sourceBytes = [Convert]::FromBase64String($sourceBase64)
[IO.File]::WriteAllBytes($target,$sourceBytes)
$projectText = $projectText.Replace($anchor, $anchor + "`r`n" + '    <Compile Include="Navigation\MoonEncounterEvaluator.cs" />')
[IO.File]::WriteAllText($project,$projectText)
$testText = $testText.Replace($testAnchor, $testAnchor + "`r`n" + '        Run("moon finite-SOI entry and periapsis diagnostics", MoonEncounterFoundation);')
$testMethod = @'
    private static void MoonEncounterFoundation()
    {
        OrbitalElements craft = new OrbitalElements
        {
            ReferenceBodyName = "Kerbin", SemiMajorAxisMeters = 700000,
            Eccentricity = 0, InclinationDegrees = 0,
            LongitudeOfAscendingNodeDegrees = 0,
            ArgumentOfPeriapsisDegrees = 0,
            EpochUniversalTimeSeconds = 0, MeanAnomalyAtEpochRadians = 0
        };
        CelestialBodyState mun = new CelestialBodyState
        {
            Name = "Mun", ParentName = "Kerbin", RadiusMeters = 200000,
            SoiRadiusMeters = 2400000, GravParameter = 6.5138398e10,
            Orbit = new OrbitalElements
            {
                ReferenceBodyName = "Kerbin", SemiMajorAxisMeters = 12000000,
                Eccentricity = 0, InclinationDegrees = 0,
                LongitudeOfAscendingNodeDegrees = 0,
                ArgumentOfPeriapsisDegrees = 0,
                EpochUniversalTimeSeconds = 0, MeanAnomalyAtEpochRadians = 2.0
            }
        };
        MoonTransferCandidate candidate;
        Check(MoonTransferBootstrap.TryFindInjection(craft, mun, 3.5316e12,
            0, 4000, 18000, 40000, 9, 9, out candidate),
            "moon bootstrap missing for SOI regression");
        MoonEncounterAssessment assessment;
        Check(MoonEncounterEvaluator.TryAssess(craft, mun, 3.5316e12,
            candidate, 300000, out assessment),
            "moon point-intercept seed failed to cross finite SOI");
        Check(assessment.EntersSoi &&
            assessment.EntryUniversalTimeSeconds > candidate.DepartureUniversalTimeSeconds &&
            assessment.EntryUniversalTimeSeconds < candidate.ArrivalUniversalTimeSeconds &&
            assessment.PredictedPeriapsisRadiusMeters >= 0 &&
            !double.IsNaN(assessment.PeriapsisErrorMeters) &&
            !assessment.RequestedPeriapsisSatisfied,
            "moon evaluator reported unsafe point-intercept as targeted safe periapsis");
        Check(!MoonEncounterEvaluator.TryAssess(craft, mun, 3.5316e12,
            candidate, double.NaN, out assessment),
            "moon evaluator accepted invalid desired periapsis");
    }

'@
$testText = $testText.Replace($methodAnchor, $testMethod + $methodAnchor)
[IO.File]::WriteAllText($tests,$testText)
Write-Host 'KMC 14.24.2 finite-SOI assessment patch applied.'
Write-Host "Backup: $backup"
Write-Host 'Run NavigationTests. KSP Plugin/Shared DLLs do not need replacement.'

